import {
  ChevronRight,
  FolderGit2,
  GitBranch,
  Laptop,
  RefreshCw,
  Terminal as TerminalIcon,
} from "lucide-react";
import React, { useMemo, useState } from "react";

export type RemoteSessionItem = {
  sessionId: string;
  title?: string | null;
  workspaceId?: string | null;
  worktreeLabel?: string | null;
  running: boolean;
};

/** Minimal project identity needed to place a session under its owning project. */
export type RemoteProjectSummary = {
  workspaceId: string;
  repoRoot?: string | null;
};

export type RemoteHierarchyState = {
  sessions: RemoteSessionItem[];
  projects?: RemoteProjectSummary[] | null;
  activeWorkspaceId?: string | null;
};

export type WorktreeSessionGroup = {
  /** Internal, render-stable identity. Never displayed. */
  key: string;
  /** Safe-to-display label. Never a raw local absolute path. */
  label: string;
  sessions: RemoteSessionItem[];
};

export type ProjectSessionGroup = {
  /** Internal, render-stable identity. Never displayed. */
  key: string;
  /** Safe-to-display label. Never a raw local absolute path. */
  label: string;
  isActive: boolean;
  isUngrouped: boolean;
  worktreeGroups: WorktreeSessionGroup[];
};

const UNGROUPED_PROJECT_KEY = "__ungrouped-project__";
const UNGROUPED_WORKTREE_LABEL = "Ungrouped";

/**
 * Groups sessions into project -> worktree buckets for accordion rendering.
 *
 * - Sessions whose `workspaceId` doesn't match a known project (or is missing
 *   entirely, e.g. sessions-only/non-workspace mode) fall into a synthetic
 *   "Ungrouped" project bucket instead of being dropped or crashing the tree.
 * - Worktree group keys are namespaced by their owning project key so two
 *   projects that happen to share a worktree label (including the literal
 *   "Ungrouped" fallback) never collapse into a single group.
 * - Display labels only ever come from `workspaceId`/`worktreeLabel`, both of
 *   which the backend already derives as short, human-readable strings
 *   (branch names or single path segments) -- never a raw local filesystem
 *   path -- so we never need to (and never do) render one here.
 */
export function buildHierarchy(state: RemoteHierarchyState): ProjectSessionGroup[] {
  const projects = state.projects ?? [];
  const knownProjectIds = new Set(projects.map((p) => p.workspaceId));
  const projectOrder = [...projects.map((p) => p.workspaceId), UNGROUPED_PROJECT_KEY];

  type MutableProjectGroup = {
    label: string;
    isActive: boolean;
    isUngrouped: boolean;
    worktrees: Map<string, WorktreeSessionGroup>;
  };
  const projectGroups = new Map<string, MutableProjectGroup>();

  const ensureProject = (key: string): MutableProjectGroup => {
    let group = projectGroups.get(key);
    if (!group) {
      const isUngrouped = key === UNGROUPED_PROJECT_KEY;
      group = {
        label: isUngrouped ? "Ungrouped" : key,
        isActive: !isUngrouped && key === state.activeWorkspaceId,
        isUngrouped,
        worktrees: new Map(),
      };
      projectGroups.set(key, group);
    }
    return group;
  };

  for (const session of state.sessions) {
    const projectKey =
      session.workspaceId && knownProjectIds.has(session.workspaceId)
        ? session.workspaceId
        : UNGROUPED_PROJECT_KEY;
    const project = ensureProject(projectKey);

    const worktreeLabel = session.worktreeLabel?.trim() || UNGROUPED_WORKTREE_LABEL;
    const worktreeKey = `${projectKey}::${worktreeLabel}`;
    let worktreeGroup = project.worktrees.get(worktreeKey);
    if (!worktreeGroup) {
      worktreeGroup = { key: worktreeKey, label: worktreeLabel, sessions: [] };
      project.worktrees.set(worktreeKey, worktreeGroup);
    }
    worktreeGroup.sessions.push(session);
  }

  const result: ProjectSessionGroup[] = [];
  for (const key of projectOrder) {
    const group = projectGroups.get(key);
    if (!group || group.worktrees.size === 0) continue;
    result.push({
      key,
      label: group.label,
      isActive: group.isActive,
      isUngrouped: group.isUngrouped,
      worktreeGroups: [...group.worktrees.values()],

