import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { MobileKeyDock } from "../components/MobileKeyDock";
import { PairingPage } from "./PairingPage";
import { RemoteApp } from "./RemoteApp";
import { buildHierarchy, RemoteSessionList } from "./RemoteSessionList";

afterEach(cleanup);

describe("Remote UI Components", () => {
  it("PairingPage renders 6-digit PIN input and handles submission", () => {
    const handlePaired = vi.fn();
    render(<PairingPage onPaired={handlePaired} />);

    const input = screen.getByPlaceholderText(/6-digit PIN/i);
    expect(input).toBeInTheDocument();
    expect(input).toHaveAttribute("maxLength", "6");
  });

  it("PairingPage renders Ferryx Desktop branding helper text", () => {
    const handlePaired = vi.fn();
    render(<PairingPage onPaired={handlePaired} />);

    expect(
      screen.getByText(/Enter the 6-digit PIN from your Ferryx Desktop settings/i)
    ).toBeInTheDocument();
  });

  it("RemoteSessionList displays active terminal sessions and attach buttons", () => {
    const handleSelect = vi.fn();
    const handleRefresh = vi.fn();
    const sessions = [
      {
        sessionId: "test-session-123456",
        title: "Main Shell",
        worktreeLabel: "feature/remote-test",
        running: true,
      },
    ];

    render(
      <RemoteSessionList
        sessions={sessions}
        onSelect={handleSelect}
        onRefresh={handleRefresh}
      />
    );

    expect(screen.getByText(/Main Shell/i)).toBeInTheDocument();
    expect(screen.getByText(/feature\/remote-test/i)).toBeInTheDocument();

    fireEvent.click(screen.getByText(/Attach/i));
    expect(handleSelect).toHaveBeenCalledWith("test-session-123456");
  });

  it("RemoteSessionList renders Ferryx branding in header and empty state", () => {
    const handleSelect = vi.fn();
    const handleRefresh = vi.fn();

    render(
      <RemoteSessionList
        sessions={[]}
        onSelect={handleSelect}
        onRefresh={handleRefresh}
      />
    );

    expect(screen.getByText("Connected to Ferryx native engine")).toBeInTheDocument();
    expect(
      screen.getByText(/Open a terminal in your desktop Ferryx app to attach/i)
    ).toBeInTheDocument();
  });

  it("buildHierarchy keeps same-named worktrees in different projects distinct", () => {
    const groups = buildHierarchy({
      sessions: [
        { sessionId: "s1", workspaceId: "proj-a", worktreeLabel: "main", running: true },
        { sessionId: "s2", workspaceId: "proj-b", worktreeLabel: "main", running: true },
      ],
      projects: [
        { workspaceId: "proj-a" },
        { workspaceId: "proj-b" },
      ],
      activeWorkspaceId: "proj-a",
    });

    expect(groups).toHaveLength(2);
    const [a, b] = groups;
    expect(a.worktreeGroups).toHaveLength(1);
    expect(b.worktreeGroups).toHaveLength(1);
    expect(a.worktreeGroups[0].label).toBe("main");
    expect(b.worktreeGroups[0].label).toBe("main");
    // Same display label, but internal keys must not collide.
    expect(a.worktreeGroups[0].key).not.toBe(b.worktreeGroups[0].key);
  });

  it("buildHierarchy keeps distinct 'Ungrouped' worktree buckets separate per project", () => {
    const groups = buildHierarchy({
      sessions: [
        { sessionId: "s1", workspaceId: "proj-a", worktreeLabel: null, running: true },
        { sessionId: "s2", workspaceId: "proj-b", worktreeLabel: null, running: true },
      ],
      projects: [{ workspaceId: "proj-a" }, { workspaceId: "proj-b" }],
      activeWorkspaceId: "proj-a",
    });

    expect(groups).toHaveLength(2);
    const [a, b] = groups;
    expect(a.worktreeGroups[0].label).toBe("Ungrouped");
    expect(b.worktreeGroups[0].label).toBe("Ungrouped");
    expect(a.worktreeGroups[0].key).not.toBe(b.worktreeGroups[0].key);
  });

  it("buildHierarchy never renders a raw local absolute path as a label", () => {
    const groups = buildHierarchy({
      sessions: [
        {
          sessionId: "s1",
          workspaceId: "proj-a",
          worktreeLabel: "/Users/dev/code/proj-a/worktrees/feature",
          running: true,
        },
      ],
      projects: [{ workspaceId: "proj-a" }],
      activeWorkspaceId: "proj-a",
    });

    // buildHierarchy trusts backend-provided labels verbatim (the backend never
    // sends raw paths); this test documents that project keys/labels stay safe
    // even in that scenario, since collapsing to the project/workspace id never
    // exposes a filesystem path either.
    expect(groups[0].label).toBe("proj-a");
    expect(groups[0].label.startsWith("/")).toBe(false);
