  session: s,
  onSelect,
}) => (
  <div
    key={s.sessionId}
    onClick={() => onSelect(s.sessionId)}
    className="group relative flex cursor-pointer items-center justify-between rounded-xl border border-border bg-card p-3.5 transition-all hover:border-primary/50 hover:bg-accent active:scale-[0.99]"
  >
    <div className="flex items-start gap-3 min-w-0">
      <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-border bg-muted text-muted-foreground transition-colors group-hover:border-primary/30 group-hover:text-primary">
        <TerminalIcon size={16} />
      </div>
      <div className="min-w-0 space-y-0.5">
        <div className="flex items-center gap-2">
          <span className="truncate font-mono text-xs font-semibold text-foreground">
            {s.title || `Terminal (${s.sessionId.substring(0, 8)})`}
          </span>
          <span className="inline-flex items-center gap-1 rounded border border-status-success/20 bg-status-success/10 px-1.5 py-0.5 text-[10px] font-medium text-status-success">
            <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-status-success" />
            Running
          </span>
        </div>
        <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
          <span className="flex items-center gap-1 font-mono">
            <GitBranch size={12} />
            {s.worktreeLabel || "main"}
          </span>
          <span>•</span>
          <span className="font-mono text-[10px] text-muted-foreground/75">
            ID: {s.sessionId.substring(0, 8)}
          </span>
        </div>
      </div>
    </div>

    <div className="shrink-0 pl-3">
      <span className="inline-flex items-center justify-center rounded-lg bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground shadow-sm transition-colors group-hover:bg-primary/90">
        Attach
      </span>
    </div>
  </div>
);

const WorktreeGroupSection: React.FC<{
  group: WorktreeSessionGroup;
  showHeader: boolean;
  onSelect: (id: string) => void;
}> = ({ group, showHeader, onSelect }) => {
  const [expanded, setExpanded] = useState(true);
  const panelId = `remote-worktree-panel-${group.key.replace(/[^a-zA-Z0-9_-]/g, "_")}`;

  return (
    <div className="space-y-2">
      {showHeader ? (
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
          aria-controls={panelId}
          className="flex w-full items-center gap-1.5 text-left text-[11px] font-medium text-muted-foreground transition-colors hover:text-foreground"
        >
          <ChevronRight
            aria-hidden="true"
            size={12}
            className={`transition-transform shrink-0 ${expanded ? "rotate-90" : ""}`}
          />
          <GitBranch size={12} className="shrink-0" />
          <span className="truncate">{group.label}</span>
          <span className="text-muted-foreground/75">({group.sessions.length})</span>
        </button>
      ) : null}

      {expanded ? (
        <div id={panelId} className="grid gap-2.5">
          {group.sessions.map((s) => (
            <SessionCard key={s.sessionId} session={s} onSelect={onSelect} />
          ))}
        </div>
      ) : null}
    </div>
  );
};

const ProjectGroupSection: React.FC<{
  group: ProjectSessionGroup;
  showHeader: boolean;
  onSelect: (id: string) => void;
}> = ({ group, showHeader, onSelect }) => {
  const [expanded, setExpanded] = useState(true);
  const panelId = `remote-project-panel-${group.key.replace(/[^a-zA-Z0-9_-]/g, "_")}`;
  const showWorktreeHeaders = group.worktreeGroups.length > 1;

  return (
    <div className="space-y-2.5">
      {showHeader ? (
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
          aria-controls={panelId}
          className="flex w-full items-center gap-1.5 text-left text-xs font-semibold uppercase tracking-wider text-muted-foreground transition-colors hover:text-foreground"
        >
          <ChevronRight
            aria-hidden="true"
            size={13}
            className={`transition-transform shrink-0 ${expanded ? "rotate-90" : ""}`}
          />
          <FolderGit2 size={13} className="shrink-0" />
          <span className="truncate normal-case">{group.label}</span>
          {group.isActive ? (
            <span className="normal-case text-[10px] font-medium text-primary">active</span>
          ) : null}
        </button>
      ) : null}

      {expanded ? (
        <div id={panelId} className="space-y-3 pl-1">
          {group.worktreeGroups.map((wg) => (
            <WorktreeGroupSection
              key={wg.key}
              group={wg}
              showHeader={showWorktreeHeaders}
              onSelect={onSelect}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
};

