      activeWorkspaceId: "proj-a",
    });

    expect(groups).toHaveLength(1);
    expect(groups[0].isUngrouped).toBe(true);
    expect(groups[0].label).toBe("Ungrouped");
    const sessionIds = groups[0].worktreeGroups.flatMap((wg) => wg.sessions.map((s) => s.sessionId));
    expect(sessionIds.sort()).toEqual(["s1", "s2"]);
  });

  it("buildHierarchy handles sessions-only mode with no project metadata at all", () => {
    const groups = buildHierarchy({
      sessions: [{ sessionId: "s1", running: true }],
    });

    expect(groups).toHaveLength(1);
    expect(groups[0].isUngrouped).toBe(true);
    expect(groups[0].worktreeGroups).toHaveLength(1);
    expect(groups[0].worktreeGroups[0].label).toBe("Ungrouped");
  });

  it("RemoteSessionList renders accessible accordion toggles with aria-expanded that collapse on click", () => {
    const handleSelect = vi.fn();
    const handleRefresh = vi.fn();

    render(
      <RemoteSessionList
        sessions={[
          { sessionId: "s1", workspaceId: "proj-a", worktreeLabel: "main", running: true },
          { sessionId: "s2", workspaceId: "proj-b", worktreeLabel: "main", running: true },
        ]}
        projects={[{ workspaceId: "proj-a" }, { workspaceId: "proj-b" }]}
        activeWorkspaceId="proj-a"
        onSelect={handleSelect}
        onRefresh={handleRefresh}
      />
    );

    const projectToggles = screen.getAllByRole("button", { expanded: true }).filter((btn) =>
      /proj-a|proj-b/.test(btn.textContent || "")
    );
    expect(projectToggles.length).toBeGreaterThanOrEqual(2);

    const toggle = projectToggles[0];
    expect(toggle).toHaveAttribute("aria-expanded", "true");
    fireEvent.click(toggle);
    expect(toggle).toHaveAttribute("aria-expanded", "false");
  });

  it("MobileKeyDock dispatches primary key actions and latches Ctrl/Alt modifiers", () => {
    const handleSendKey = vi.fn();
    render(<MobileKeyDock onSendKey={handleSendKey} />);

    fireEvent.click(screen.getByText("Ctrl-C"));
    expect(handleSendKey).toHaveBeenCalledWith("ctrl-c");

    fireEvent.click(screen.getByText("Tab"));
    expect(handleSendKey).toHaveBeenCalledWith("tab");

    // Latch Ctrl + C
    fireEvent.click(screen.getByText("Ctrl"));
    fireEvent.click(screen.getByText("Tab"));
    expect(handleSendKey).toHaveBeenCalledWith("ctrl-tab");
  });

  it("RemoteApp renders Ferryx Remote in header and does not contain rorca", () => {
    localStorage.setItem("ferryx_remote_token", "test-token-xyz");
    render(<RemoteApp />);

    const header = screen.getByRole("banner");
    expect(header).toHaveTextContent(/Ferryx Remote/i);
    expect(header.textContent).not.toContain("rorca");
    localStorage.clear();
  });

  it("RemoteApp supports legacy rorca_remote_token with Ferryx Remote header", () => {
    localStorage.setItem("rorca_remote_token", "legacy-token-123");
    render(<RemoteApp />);

    const header = screen.getByRole("banner");
    expect(header).toHaveTextContent(/Ferryx Remote/i);
    expect(header.textContent).not.toContain("rorca");
    localStorage.clear();
  });
});

